using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    //  CalculateTotal – DataRow (inline constants)
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.20, 0.00,   DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.0, 2, 1.0,  400.00, DisplayName = "100% tax doubles the subtotal")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – invalid inputs
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1, 0.10, DisplayName = "Negative unit price")]
    public void CalculateTotal_NegativePrice_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.0, -1, 0.10, DisplayName = "Negative quantity")]
    public void CalculateTotal_NegativeQuantity_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.0, 1, -0.01, DisplayName = "Tax rate below 0")]
    [DataRow(10.0, 1, 1.01,  DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (method source)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> ValidDiscountCases
    {
        get
        {
            yield return new object[] { 200.00m, 0m,   200.00m }; // no discount
            yield return new object[] { 200.00m, 10m,  180.00m }; // 10% off
            yield return new object[] { 200.00m, 25m,  150.00m }; // 25% off
            yield return new object[] { 200.00m, 50m,  100.00m }; // half off
            yield return new object[] { 200.00m, 100m, 0.00m };   // free
            yield return new object[] { 0.00m,   50m,  0.00m };   // zero price
            yield return new object[] { 79.99m,  15m,  67.9915m };// fractional result
        }
    }

    [TestMethod]
    [DynamicData(nameof(ValidDiscountCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (invalid inputs)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, -1m };    // below range
            yield return new object[] { 100.00m, 100.01m };// above range
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases))]
    public void ApplyDiscount_InvalidDiscount_Throws(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }
}

